WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    try { if (typeof hmFS !== 'undefined') variantIdx = Number(hmFS.SysProGetInt('dialcraft_variant')) || 0 } catch (e) {}

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x0c0c0e,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('scene_f07.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(202),
      minute_startY: px(60),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_f2g9,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon Main (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(182),
      y: px(67),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(70),
      hour_startY: px(61),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Main_nfok,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(210),
      minute_startY: px(179),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_33ig,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(182),
      y: px(186),
      src: A('symbol_u003a_2.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(62),
      hour_startY: px(179),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_33qd,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(12),
      y: px(133),
      week_en: img_Weekday_w540,
      week_sc: img_Weekday_w540,
      week_tc: img_Weekday_w540,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(257),
      day_startY: px(143),
      day_zero: 0,
      day_space: px(0),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_h5al,
      day_sc_array: img_Day_h5al,
      day_tc_array: img_Day_h5al,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(216),
      y: px(204),
      type: ui.data_type.STEP,
      font_array: img_Steps_p7jv,
      align_h: ui.align.RIGHT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Heart rate (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(274),
      y: px(246),
      type: ui.data_type.HEART,
      font_array: img_Heart_rate_14pq,
      align_h: ui.align.RIGHT,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Battery (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(241),
      y: px(288),
      type: ui.data_type.BATTERY,
      font_array: img_Battery_k4pj,
      align_h: ui.align.RIGHT,
      unit_en: A('percent.png'),
      unit_sc: A('percent.png'),
      unit_tc: A('percent.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Temperature (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(252),
      y: px(331),
      type: ui.data_type.WEATHER_CURRENT,
      font_array: img_Temperature_035c,
      align_h: ui.align.RIGHT,
      unit_en: A('degree.png'),
      unit_sc: A('degree.png'),
      unit_tc: A('degree.png'),
      negative_image: A('negative.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Paper cover (IMG)
    const variants_0 = [A('sp/cover_001.png'), A('sp/cover_000.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(6),
      y: px(26),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.cover = variant_0
    F.cover = variants_0

    // Print head (IMG)
    const variants_1 = [A('sp/head_003.png'), A('sp/head_002.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(14),
      y: px(32),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.head = variant_1
    F.head = variants_1

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length)
      try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt('dialcraft_variant', variantIdx) } catch (e) {}
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      // Bon fiscal: each minute the receipt is printed line by line from the top, held, and wiped
      const MS = 100, PT = 32, PH = 388, PX = 14, LH = 36;
      const V = {"cover":{"__blank":0,"s":1},"head":{"__blank":0,"s":1}};
      const ease = (t) => { t = Math.max(0, Math.min(1, t)); return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; };
      const tick = () => {
        const now = Date.now(), d = new Date(now), sec = d.getSeconds() + (now % 1000) / 1000;
        let cy = PT - 6, ch = PH + 6;
        if (sec < 0.6) { /* paper still blank */ }
        else if (sec < 6.0) { const r = Math.round(ease((sec - 0.6) / 5.4) * PH / LH) * LH; cy = PT - 6 + r; ch = PH + 6 - r; }
        else if (sec < 58.6) { ch = 0; }
        else { const k = ease((sec - 58.6) / 1.0); ch = Math.round((PH + 6) * k); }
        if (ch > 1) slot('cover')(PX - 8, cy, V.cover.s, 286, ch); else slot('cover').hide();
        if (sec >= 0.6 && sec < 6.0 && ch > 1) slot('head')(PX, cy - 3, V.head.s); else slot('head').hide();
      };
        // ---- shared runtime: slot setter that skips unchanged calls, and a loop that runs only while the face is on screen ----
      const SL = {};
      const slot = (h) => {
        if (SL[h]) return SL[h];
        const w = W[h], f = F[h]; let key = '';
        const s = (x, y, i, ww, hh) => {
          const k = x + '|' + y + '|' + i + '|' + ww + '|' + hh;
          if (k === key) return;
          key = k;
          const p = { x: pxv(x), y: pxv(y) };
          if (i !== undefined) p.src = f[i];
          if (ww !== undefined) { p.w = pxv(ww); p.h = pxv(hh); }
          w.setProperty(ui.prop.MORE, p);
        };
        s.hide = () => { if (key === 'hide') return; key = 'hide'; w.setProperty(ui.prop.MORE, { src: f[V[h].__blank] }); };
        return (SL[h] = s);
      };
      let gen = 0, running = false;
      const safe = () => { try { tick(); } catch (e) { /* a bad frame must not stop the loop */ } };
      const loop = (g) => {
        if (!running || g !== gen) return;
        safe();
        if (running && g === gen) { try { setTimeout(() => loop(g), MS); } catch (e) {} }
      };
      const start = () => {
        gen++; running = true; const g = gen;
        try { setTimeout(() => loop(g), MS); } catch (e) {}
        safe();
      };
      const stop = () => { running = false; gen++; };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: start, pause_call: stop });
      start();

    }
  },

  build() {
    this.initView()
  },
})
